/*---
description: NFKD agrees with Node for every code point U+010000 through U+01FFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Node 24.20.0, Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [1821222092, 2069607370, 3748979141, 3662897605, 418361797, 1223811525, 772480954, 3661109701, 3498140101, 3388834245, 1684883909, 2771642821, 205892197, 4117756647, 1900481714, 979783909];
const blocks = ["NFKD U+010000-U+010FFF", "NFKD U+011000-U+011FFF", "NFKD U+012000-U+012FFF", "NFKD U+013000-U+013FFF", "NFKD U+014000-U+014FFF", "NFKD U+015000-U+015FFF", "NFKD U+016000-U+016FFF", "NFKD U+017000-U+017FFF", "NFKD U+018000-U+018FFF", "NFKD U+019000-U+019FFF", "NFKD U+01A000-U+01AFFF", "NFKD U+01B000-U+01BFFF", "NFKD U+01C000-U+01CFFF", "NFKD U+01D000-U+01DFFF", "NFKD U+01E000-U+01EFFF", "NFKD U+01F000-U+01FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 65536 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFKD");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
